INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spectar', 'Spectar, released by Exidy in 1980, is the follow-up of Targ. Gameplay is apparently unchanged, you control a vehicle called Whummel into a 9x9 grid maze, chasing down, and being chased by, the alien invaders. Targs have evolved into the more dangerous Rammers, and Spectars appears more often, shooting at player''s ship.
