INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sky Chuter', 'In Sky Chuter, the player guides their missile launcher that must fire at planes that appear from the left and right edges of the screen, then make their way down towards the player. While they are homing in on the player, not only do the planes fire down on the player, but they also release parachutes containing bombs that must be dealt with before they reach the surface. Once the player manages to kill the last airplane, the game proceeds to the next pattern. If the player loses all their lives, the game ends.' FROM games WHERE igdb_id = 328226 ON CONFLICT (game_id, language_code) DO NOTHING;
