INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire', 'Fire is a silver type Game & Watch video game unit that was initially released on July 31, 1980. The game is one of the best selling in the Game & Watch series selling an astonishing (albeit estimated) 1,000,000 copies worldwide. A re-release for the game was made for the Wide Screen units, which sold 200,000 more units that the silver edition. This particular version of the game was released on December 4, 1981.
