INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oldorf''s Revenge', 'You have to find treasure and reach an minimum pf 300 points in order to finish the game. There are seven different classes which you can choose from: Gladiator, Cleric, Strongman, Wizard, Elf, Thief and Magician. You will have to switch classes during your adventure for every class has certain abilities which the other classes do not have. But you may only change every class five times during the game. Each time you switch classes you will loose hit points. Which you will also loose when you encounter monsters on your travels.' FROM games WHERE igdb_id = 24847 ON CONFLICT (game_id, language_code) DO NOTHING;
