INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Steel Worker', 'Steel Worker is a reflex game that combines OH&S with the Japanese practice of just in time manufacturing. Each level starts with a mindless worker moving steadily from one side of the factory to the other along an incomplete gantry. To prevent the worker from falling to his doom, the player must select another piece of the gantry to be erected by the time the worker reaches the end of the current one. The process is repeated until the worker makes it to safety at the platform at the other end of the screen, or four workers have died. Complicating matters are a pair of elevators in the centre of the screen whose touch will be fatal to the steel worker.
