INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skiing', 'In Skiing, your goal is to ski to the bottom of the mountain in the shortest time possible. The mountain is treacherous with plenty of trees and moguls in the way! There are two different modes of gameplay. In slalom mode, there are a series of gates you need to ski through; missing any will result in a penalty to your time. In downhill mode you just need to ski to the bottom as fast as possible. Each mode includes five different skill levels which affect the length of the course (and the number of gates in slalom mode.)' FROM games WHERE igdb_id = 5686 ON CONFLICT (game_id, language_code) DO NOTHING;
