INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Invaders II', 'Like the classic original, this game requires the player to destroy advancing invader ships. This game has a competitive mode where two players fight to destroy each other in addition to the advancing attackers. Space Invaders II was only released in a cocktail table format.' FROM games WHERE igdb_id = 46839 ON CONFLICT (game_id, language_code) DO NOTHING;
