INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blockout! / Breakdown!', 'In Blockout!, the object is to blast through the blocks in the shortest amount of time. There are four colored lines of blocks, and each line has an electronic demon. The electronic demons can replace removed blocks when charged. They''ll be charged by touching either sides of the screen. After placing a block, they''ll lose the charge, and if they try to cross a gap uncharged, they''ll fall and reappear after a penalty time.' FROM games WHERE igdb_id = 119154 ON CONFLICT (game_id, language_code) DO NOTHING;
