INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Castle', 'Star Castle is a 1980 vector arcade game by Cinematronics. The game involves obliterating a series of defenses orbiting a stationary turret in the center of the screen. The game was designed by Tim Skelly and programmed by Scott Boden. Tim Skelly also created a number of other Cinematronics titles, including Starhawk, Armor Attack and Rip-Off. As with many other titles by the company, Star Castle was ported to the Vectrex video game console in 1983.' FROM games WHERE igdb_id = 18731 ON CONFLICT (game_id, language_code) DO NOTHING;
