INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Olympic Decathlon', 'Olympic Decathlon is a sports game written by Timothy W. Smith for the TRS-80 and published in 1980 by Microsoft. In the game, the player competes in ten track and field events. The gold medalist for decathlon in the Montreal 1976 Summer Olympics, Bruce Jenner, is a character. It was ported to the Apple II in 1981.' FROM games WHERE igdb_id = 78618 ON CONFLICT (game_id, language_code) DO NOTHING;
