INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TV Vader', '"TV Vader" is an arrangement of Taito''s "Space Invaders" released by Epoch as a home video game in 1980. It is an early video game machine classified as the first generation. 8 horizontal x 6 rows of invaders appear, but due to performance limitations, only the front row invaders are displayed. Although it was a low-performance game machine, it successfully reproduced the atmosphere of Space Invaders. In 1982, it was ported to Cassette Vision under the name "Battle Vader".' FROM games WHERE igdb_id = 250900 ON CONFLICT (game_id, language_code) DO NOTHING;
