INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lupin III', 'You play Lupin, a character who is trying to get money for his sweetheart. You try to take up to two of the six bags from the top and get them to the bottom without getting caught by an enemy. If an enemy gets too close or you are surrounded you can teleport, but there is no telling where you will end up -- you could end up in a worse spot than the one you escaped from! 
