INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fracas', 'Fracas is Stuart Smith''s very first game, using the game system which would later develop into Ali Baba and the Forty Thieves and ultimately Adventure Construction Set. Like those games, it is combat-oriented turn-based RPG and one of its main features is the large numbers of characters, both good and bad, that can get involved in the battles at once. You may control one or more characters in the game, and move them about fighting bad guys and gaining treasures.' FROM games WHERE igdb_id = 25691 ON CONFLICT (game_id, language_code) DO NOTHING;
