INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Indian Battle', 'The player takes control of a cowboy battling Native Americans. There are three types of enemies including the Indian footman, Indian on horseback and Buzzard. Arrow and tomahawk projectiles can also be shot for points. Enemies on the same plane such as scorpions cannot be shot and limit where the player can move the cowboy. Obstacles such as cacti and rocks block the cowboy''s line of fire. One hit from an enemy or projectile takes a life away. The player is required to kill a set number of enemies to progress to the next level.' FROM games WHERE igdb_id = 91665 ON CONFLICT (game_id, language_code) DO NOTHING;
