INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Computer Napoleonics: The Battle of Waterloo', 'Computer Napoleonics: The Battle of Waterloo is a division level simulation of the Battle of Waterloo. It can be played by one or two players. One player commands the forces on Napoleon while the other player (or the computer) commands the forces of the Anglo-Allied-Prussia armies. Take turns by moving armies in position and engaging in combat. Turns continue this way for ten game turns or until one side has successfully fulfilled its victory conditions. Each game turn lasts about one hour of real time.' FROM games WHERE igdb_id = 25242 ON CONFLICT (game_id, language_code) DO NOTHING;
