INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quasar Commander', 'Quasar Commander is an exciting game of skill to play on your TRS-80 color computer. You are at the helm of a Starship. Imagine that your video screen is a window looking into outerspace. Your laser sights are in the center of this "viewscreen". Try to destroy as many enemy ships as possible before colliding with them. This game contains variations for countless hours of fun.' FROM games WHERE igdb_id = 44337 ON CONFLICT (game_id, language_code) DO NOTHING;
