INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cosmic Alien', 'Cosmic Alien is an arcade game that is a clone of Galaxian. Players control a gun at the bottom of the screen that shoots at aliens (which are known as "chiefs", "guards", "commanders", or "soldiers") that are in a formation overhead. Aliens begin peeling off the formation and fly towards the bottom of the screen while dropping bombs. There are two flagship-type aliens (chiefs) at the top of the screen that can fly accompanied with one or more escort (guard) aliens; shooting one or more of the guards before shooting a chief will increase the amount of the chief’s score. If a player does not shoot an alien (or if it doesn’t ram the player’s gun) during its attack run it will return to the formation.
