INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Radar Scope', 'Radar Scope is a 1980 fixed shooter arcade game developed by Nintendo R&D2 and published by Nintendo. The player assumes the role of the Sonic Spaceport starship and must wipe out formations of an enemy race known as the Gamma Raiders before they destroy the player''s space station. Gameplay is similar to Space Invaders and Galaxian, but set in a forced perspective angle.
