INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Electric Company Math Fun', 'Math fun is an educational game which can be played by one or two players. Each player controls a gorilla which is wandering through the jungle. As the gorilla walks on, it will encounter a creature which has a math problem with it. You need to enter in the correct answer to the problem as quickly as possible. If you get the answer correct, your gorilla may continue on. If you get the answer wrong, then your gorilla must jump into the river. Your gorilla is unable to leave the river and continue on until you answer another math problem correctly. The goal is to correctly answer as many of the problems as you can in the shortest amount of time. The game includes eighteen different levels of difficulty which can be set individually for each player.' FROM games WHERE igdb_id = 41436 ON CONFLICT (game_id, language_code) DO NOTHING;
