INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('checkers--2', 131515, '1980-09-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co76q4.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Checkers', 'Challenge Tradition! Beat a friend electronically for practice. Then go for it against the Ultimate Checker Player - a Wiley computer who asks and gives no quarter. - Two ways to play, vs. a friend or the ultimate competitor, the canny computer. - HI and LO skill levels when playing the computer. Added difficulty... added excitement. - "Bail Out" button - COMPUTER SUGGESTS MOVE, when you''re stumped against the computer. - Simulated sound effects - BELLS, BUZZERS, A BRONX CHEER and a VICTORY TUNE. - No time limit on moves! - CLEAR button that lets you change your move!' FROM games WHERE igdb_id = 131515 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 131515 AND p.igdb_id = 67 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('abpa-backgammon', 5653, '1980-10-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1pj3.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ABPA Backgammon', 'Intellivision Backgammon is identical with the board game. Backgammon is a game played by two players (the computer can be one of the players). Each player has 15 pieces. The object of the game is to be the first to move all your pieces completely around and finally off the board. Moving your pieces off the board is called "bearing off". The first player to bear off all his pieces is the winner. Each player moves in a direction beginning from his opponent''s Home Table and coming around to his own Home Table. Thus one player always moves clockwise and the other always counterclockwise. You can play against the computer at two skill levels - one for beginners or intermediate, another for experts - or two players can compete against each other. It displays the American Backgammon Players Association (ABPA) logo.' FROM games WHERE igdb_id = 5653 ON CONFLICT (game_id, language_code) DO NOTHING;
