INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crazy Balloon', 'The player controls a box tied to a floating balloon, which swings left and right continually, within a maze filled with spikes. Any contact with the spikes, either with the balloon or the box, destroys the balloon. Using a four-way joystick, the player moves the box through the maze and toward the goal, ensuring that the swinging balloon avoids the spikes.
