INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Panic', 'A game remarkably similar to Lode Runner, you play an astronaut with limited oxygen (time) chased around by various space aliens. Your only method of dealing with these multicolored threats from space is to dig a hole, lure it into a hole and then manually fill up the hole with the alien in it. Dropping aliens on top of other aliens earns you extra points and eliminates both. Levels get progressively harder and enemies grow faster.' FROM games WHERE igdb_id = 18678 ON CONFLICT (game_id, language_code) DO NOTHING;
