INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Auto Racing', 'Auto Racing is a one or two player racing game that puts the player behind the wheel of one of five cars, each with different specialties. The player may race on five different fairly large courses. In the one player game, the player is racing the clock to finish five laps as quickly as possible. In the two player game, the player can race a friend and gain points for either the opponent crashing or if one is leading far enough to reach the edge of the screen.' FROM games WHERE igdb_id = 5659 ON CONFLICT (game_id, language_code) DO NOTHING;
