INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Videocart-23: Galactic Space Wars', 'In Galactic Space Wars, the player controls of a fighter spacecraft with the sole objective to find and destroy enemy space ships. The players takes a first person perspective from inside the cockpit searching the vast area of space to locate enemy craft. Once one is located, players try to quickly fix their laser''s sight on the enemy and shoot it. If the enemy stays on the screen for too long, it will fire one shot at the player''s ship and score a hit. There are four different enemy ships, each worth a varying amount of points. Players are given a limited amount of time to destroy as many ships as possible, while trying not to let the enemy ships fire back.
