INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('carnival', 5666, '1980-06-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1pjo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scpmuo.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Carnival', 'The goal of the game is to shoot at targets, while carefully avoiding running out of bullets. Three rows of targets scroll across the screen in alternating directions; these include rabbits, ducks, owls, and bonus items. If a duck target crosses the bottom row without being shot, it will come to life and begin flying down toward the player. Any ducks that reach the bottom of the screen in this manner will eat some of the player''s bullets. Objects also periodically appear among the targets that will give the player extra bullets or points when hit. A spinning wheel with eight pipes sits above the rows of moving targets; these pipes and all targets must be shot in order to complete the round.
