INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kaitei-takara-sagashi', 40214, '1980-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/irow6rp9dzkqcobsijfw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sctkis.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kaitei Takara Sagashi', 'Use the 2-way joystick to direct the boat across the surface of the ocean, then press the button to lower the diver down to the bottom of the ocean while watching out for the sharks swimming across the screen. During this time, you can hold the button to pause the diver''s descent and push the joystick in either direction to fire a harpoon at the sharks for 30-300 points apiece. Once the diver has reached the bottom of the ocean, push the joystick in either direction to make him walk towards either of the two treasure caches that are closest to him (the boat will automatically follow his movements at this point). When the diver is directly over a treasure cache, the boat will lower him into it. The amount of points you will receive when you make it back onto the surface of the ocean, which can range from 50-250, will then appear on the screen, and the boat will raise the diver back up to the surface of the ocean. Once again, you can hold the button to pause the diver''s ascent, and push the joystick in either direction to fire a harpoon at the sharks. Once you have made it back up to the surface of the ocean, you will have to repeat the entire process for each of the four remaining treasure caches before the game proceeds to the next round.' FROM games WHERE igdb_id = 40214 ON CONFLICT (game_id, language_code) DO NOTHING;
