INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eamon', 'Eamon, sometimes known by the longer title The Wonderful World of Eamon, is a role-playing adventure game created by Donald Brown and released for the Apple II in 1980. The game is a text adventure similar to other early titles like Adventure (1976) or Zork (1980) and to later text-based Multi-user dungeons (MUDs), though with many role-playing elements not available in other interactive fiction. Eamon software is non-commercial and is freely available in the public domain.' FROM games WHERE igdb_id = 28233 ON CONFLICT (game_id, language_code) DO NOTHING;
