INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sasuke vs. Commander', 'Released by SNK in 1980, it was an early shoot ''em up that featured human characters on foot instead of vehicles, spacecraft, or aliens. The player character faces off against multiple shuriken-throwing ninjas and along the way faces several bosses, such as a flame-shooting shinobi.' FROM games WHERE igdb_id = 65660 ON CONFLICT (game_id, language_code) DO NOTHING;
